1220	
1221	async function serveStatic(
1222	  req: IncomingMessage,
1223	  res: ServerResponse,
1224	  port: number
1225	): Promise<void> {
1226	  const urlPath = (req.url ?? '/').split('?')[0]!;
1227	  const filePath =
1228	    urlPath === '/' ? join(PUBLIC_DIR, 'index.html') : join(PUBLIC_DIR, urlPath.slice(1));
1229	
1230	  // Security: prevent path traversal outside PUBLIC_DIR
1231	  const resolved = resolve(filePath);
1232	  if (!resolved.startsWith(PUBLIC_DIR)) {
1233	    sendError(res, 404, 'NOT_FOUND', 'Not found.', port);
1234	    return;
1235	  }
1236	
1237	  const ext = extname(filePath);
1238	  const mimeType = MIME_TYPES[ext] ?? 'application/octet-stream';
1239	
1240	  try {
1241	    const content = await readFile(filePath);
1242	    res.writeHead(200, {
1243	      'Content-Type': mimeType,
1244	      'Content-Length': content.length,
1245	      'Cache-Control': 'no-store',
1246	      ...corsHeaders(port),
1247	      ...securityHeaders(),
1248	    });

1249	    res.end(content);
1250	  } catch {
1251	    sendError(res, 404, 'NOT_FOUND', 'Not found.', port);
1252	  }
1253	}
