 22	// ---------------------------------------------------------------------------
 23	// Helpers
 24	// ---------------------------------------------------------------------------
 25	
 26	function startTestServer(
 27	  ledgerRoot: string,
 28	  configPath: string,
 29	  logsDir: string,
 30	  bootVersions?: WorkspaceVersions,
 31	): Promise<{ server: Server; baseUrl: string }> {
 32	  return new Promise((resolve, reject) => {
 33	    const server = createServer((req, res) => {
 34	      handleRequest(req, res, ledgerRoot, configPath, 0, logsDir, bootVersions ?? null).catch(
 35	        (err) => {
 36	          process.stderr.write(`[test-server] Unhandled: ${String(err)}\n`);
 37	          if (!res.headersSent) {
 38	            res.writeHead(500, { 'Content-Type': 'application/json' });
 39	            res.end(JSON.stringify({ error: { code: 'INTERNAL_ERROR', message: 'error' } }));
 40	          }
 41	        },
 42	      );
 43	    });
 44	
 45	    server.listen(0, '127.0.0.1', () => {
 46	      const addr = server.address();
 47	      if (addr && typeof addr === 'object') {
 48	        resolve({ server, baseUrl: `http://127.0.0.1:${addr.port}` });
 49	      } else {
 50	        reject(new Error('Could not determine server port'));
 51	      }
 52	    });
 53	
 54	    server.on('error', reject);
 55	  });
 56	}
 57	
 58	function stopServer(server: Server): Promise<void> {
 59	  return new Promise((resolve, reject) => {
 60	    server.close((err) => (err ? reject(err) : resolve()));
 61	  });
 62	}
